def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_towards(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def pick_best(points, origin, prefer_far=False):
        best = None
        best_score = None
        for p in points:
            pp = pos(p, None)
            if pp is None:
                continue
            s = dist(origin, pp)
            score = -s if prefer_far else s
            if best is None or score < best_score:
                best = pp
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    me = (sx, sy)
    opp = (ox, oy)

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_towards(me, opp)
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = pick_best(corners, opp, prefer_far=True)
        if target is None:
            return [0, 0]
        return step_towards(me, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        target = pick_best(targets, me, prefer_far=False)
        if target is not None:
            return step_towards(me, target)
        # If no target cells are exposed, drift toward opponent or center.
        if obs := observation.get("center_position"):
            c = pos(obs, me)
            return step_towards(me, c)
        return step_towards(me, opp) if opp != me else [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("food") or []
    target = pick_best(resources, me, prefer_far=False)
    if target is not None:
        return step_towards(me, target)

    # Resource denial / exploration fallback.
    if env == "resource_collection":
        if opp != me:
            return step_towards(me, opp)
        return [0, 0]

    # Generic fallback: chase if near, otherwise move to a corner away from opponent.
    if gw and gh:
